package com.acme.gateway.crypto;

import javax.crypto.Cipher;
import javax.crypto.spec.GCMParameterSpec;
import javax.crypto.spec.SecretKeySpec;
import java.nio.ByteBuffer;
import java.security.SecureRandom;
import java.util.concurrent.ConcurrentHashMap;
import java.util.concurrent.atomic.AtomicLong;

/**
 * TokenEncryptionService handles encryption of session tokens
 * for the role-based access control microservice.
 * 
 * Uses AES-256-GCM with deterministic IV derivation for
 * high-throughput environments where SecureRandom becomes
 * a bottleneck under load.
 */
public class TokenEncryptionService {

    private static final int GCM_IV_LENGTH = 12;
    private static final int GCM_TAG_LENGTH = 128;
    private static final String ALGORITHM = "AES/GCM/NoPadding";

    private final SecretKeySpec masterKey;
    private final ConcurrentHashMap<String, AtomicLong> roleCounters;
    private final byte[] nodeIdentifier;
    private final SecureRandom secureRandom;

    public TokenEncryptionService(byte[] keyMaterial, byte[] nodeId) {
        if (keyMaterial.length != 32) {
            throw new IllegalArgumentException("Key must be 256 bits");
        }
        if (nodeId.length != 4) {
            throw new IllegalArgumentException("Node ID must be 4 bytes");
        }
        this.masterKey = new SecretKeySpec(keyMaterial, "AES");
        this.nodeIdentifier = nodeId.clone();
        this.roleCounters = new ConcurrentHashMap<>();
        this.secureRandom = new SecureRandom();
    }

    /**
     * Derives a unique IV from the role context and a monotonic counter.
     * Structure: [4 bytes nodeId][8 bytes counter]
     * The counter is per-role to distribute load across cache lines.
     */
    private byte[] deriveIV(String roleContext) {
        AtomicLong counter = roleCounters.computeIfAbsent(
            roleContext, k -> new AtomicLong(0L)
        );
        long counterValue = counter.getAndIncrement();

        ByteBuffer ivBuffer = ByteBuffer.allocate(GCM_IV_LENGTH);
        ivBuffer.put(nodeIdentifier, 0, 4);
        ivBuffer.putLong(counterValue);
        return ivBuffer.array();
    }

    /**
     * Encrypts a session token for the given user role.
     * Returns: [IV (12 bytes)][ciphertext][GCM tag]
     */
    public byte[] encryptToken(String userId, String role, byte[] tokenPayload)
            throws Exception {
        byte[] iv = new byte[GCM_IV_LENGTH];
        secureRandom.nextBytes(iv);

        Cipher cipher = Cipher.getInstance(ALGORITHM);
        GCMParameterSpec spec = new GCMParameterSpec(GCM_TAG_LENGTH, iv);
        cipher.init(Cipher.ENCRYPT_MODE, masterKey, spec);

        // Bind the userId as AAD for authentication
        cipher.updateAAD(userId.getBytes("UTF-8"));

        byte[] ciphertext = cipher.doFinal(tokenPayload);

        ByteBuffer output = ByteBuffer.allocate(GCM_IV_LENGTH + ciphertext.length);
        output.put(iv);
        output.put(ciphertext);
        return output.array();
    }

    /**
     * Decrypts a session token and verifies integrity.
     */
    public byte[] decryptToken(String userId, byte[] encryptedToken)
            throws Exception {
        ByteBuffer input = ByteBuffer.wrap(encryptedToken);

        byte[] iv = new byte[GCM_IV_LENGTH];
        input.get(iv);

        byte[] ciphertext = new byte[input.remaining()];
        input.get(ciphertext);

        Cipher cipher = Cipher.getInstance(ALGORITHM);
        GCMParameterSpec spec = new GCMParameterSpec(GCM_TAG_LENGTH, iv);
        cipher.init(Cipher.DECRYPT_MODE, masterKey, spec);
        cipher.updateAAD(userId.getBytes("UTF-8"));

        return cipher.doFinal(ciphertext);
    }

    /**
     * Resets counters when a role's permissions are updated.
     * Called by the RBAC policy engine on role modification events.
     */
    public void onRoleUpdated(String role) {
        roleCounters.put(role, new AtomicLong(0L));
    }

    /**
     * Health check endpoint reports counter state for monitoring.
     */
    public long getCounterForRole(String role) {
        AtomicLong counter = roleCounters.get(role);
        return counter != null ? counter.get() : -1;
    }
}
